    private List<Order> _orders = new();
    private bool _loading = true;

    protected override async Task OnInitializedAsync()
    {
        var state = await AuthProvider.GetAuthenticationStateAsync();
        var claim = state.User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;
        if (int.TryParse(claim, out var accountId))
        {
            await using var db = await DbFactory.CreateDbContextAsync();
            var customer = await db.Customers.FirstOrDefaultAsync(c => c.AccountId == accountId);
            if (customer != null)
            {
                _orders = await db.Orders
                    .Include(o => o.OrderDetails).ThenInclude(od => od.Product)
                    .Where(o => o.CustomerId == customer.Id)
                    .OrderByDescending(o => o.OrderDate)
                    .ToListAsync();
            }
        }
        _loading = false;
    }

